function bindUI(meds,td){document.querySelectorAll('[data-v]').forEach(b=>b.onclick=async()=>{view=b.dataset.v;await render()});const p=document.getElementById('period');if(p)p.onchange=async()=>{period=Number(p.value);await render()};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggle(Number(b.dataset.toggle),td,b.dataset.time));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editMed(Number(b.dataset.edit)));document.querySelectorAll('[data-end]').forEach(b=>b.onclick=()=>endMed(Number(b.dataset.end)));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const m=meds.find(x=>x.id===Number(b.dataset.mid));if(m)chooseHistorical(m,b.dataset.day)});document.querySelectorAll('.color-btn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.color-btn').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});const ls=document.getElementById('language-select');if(ls)ls.onchange=async()=>{lang=ls.value;localStorage.setItem('pillplan_lang',lang);applyLang();await render()};const tz=document.getElementById('timezone-accept');if(tz)tz.onclick=async()=>{localStorage.setItem('pillplan_timezone',deviceTimeZone());await put('meta',{key:'timeZone',value:deviceTimeZone(),confirmedAt:new Date().toISOString()});alert(tr('timezoneConfirmed'));await render()};const addTime=document.getElementById('add-time');if(addTime){addTime.onclick=()=>{const wrap=document.getElementById('time-list'),row=document.createElement('div');row.className='time-row';row.innerHTML='<input class="form-input med-time" type="time" value="12:00"><button type="button" class="time-remove">−</button>';wrap.appendChild(row);bindTimeRows()};bindTimeRows()}const add=document.getElementById('add-med');if(add)add.onclick=addMed;const imp=document.getElementById('import-btn');if(imp)imp.onclick=async()=>{const f=document.getElementById('backup-file')?.files?.[0];if(!f)return alert(tr('chooseFile'));try{await importBackup(f);alert(tr('importOk'))}catch(e){alert(tr('importFail',{err:e.message}))}};const exp=document.getElementById('export-btn');if(exp)exp.onclick=exportBackup;const rb=document.getElementById('report-btn');if(rb)rb.onclick=()=>showMedicationReport(7);const sh=document.getElementById('share-btn');if(sh)sh.onclick=shareSummary;const pr=document.getElementById('print-btn');if(pr)pr.onclick=()=>window.print();const no=document.getElementById('notify-btn');if(no)no.onclick=testNotification}

function reportTierLabel(e){
  if(!e||e.type!=='taken')return tr('open');
  if(e.tier==='red')return tr('late45');
  if(e.tier==='yellow')return tr('late30');
  if(e.tier==='unrated')return tr('backfilled');
  return tr('punctual');
}
function reportWorstTier(a,b){
  const rank={open:5,red:4,yellow:3,unrated:2,green:1};
  return (rank[b]||0)>(rank[a]||0)?b:a;
}
async function buildMedicationReport(daysCount=7){
  const meds=await all('meds'),map=await latestEvents(),days=pastDays(daysCount);
  const stats={due:0,done:0,green:0,yellow:0,red:0,unrated:0,open:0};
  const medicationRows=[];
  const dayRows=[];
  for(const m of meds){
    const relevant=days.filter(d=>timesForDate(m,d).length);
    if(!relevant.length)continue;
    const allTimes=normalizeTimes(relevant.flatMap(d=>timesForDate(m,d)));
    medicationRows.push({
      name:m.name,dose:m.dose||'',instructions:m.doctorInstructions||'',expiryDate:m.expiryDate||'',times:allTimes
    });
  }
  for(const d of days){
    for(const m of meds){
      for(const time of timesForDate(m,d)){
        stats.due++;
        const e=map[slotKey(m.id,d,time)];
        let tier='open';
        if(e&&e.type==='taken'){
          stats.done++;
          tier=e.tier==='red'?'red':e.tier==='yellow'?'yellow':e.tier==='unrated'?'unrated':'green';
          stats[tier]++;
        }else stats.open++;
        dayRows.push({date:d,name:m.name,dose:m.dose||'',time,tier,label:reportTierLabel(e)});
      }
    }
  }
  stats.pct=stats.due?Math.round(stats.done/stats.due*100):0;
  return{daysCount,start:days[0],end:days[days.length-1],stats,medicationRows,dayRows};
}
